/* =========================================================================
   1. NAVBAR COMPONENT
   ========================================================================= */
interface NavbarProps {
  onStartFree?: () => void
  onGoToStore?: () => void
  onNavClick?: (section: string) => void
}

function Navbar({ onStartFree, onNavClick }: NavbarProps) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  const handleNavClick = (section: string) => {
    onNavClick?.(section)
    setMobileMenuOpen(false)
  }

  return (
    <header className="navbar-wrapper">
      <nav className="navbar">
        <div className="navbar-container">
          {/* Brand Logo with exact uploaded logo */}
          <a
            href="#"
            className="navbar-logo"
            onClick={(e) => {
              e.preventDefault()
              handleNavClick('product')
            }}
          >
            <img
              src="/willovate-one-logo.png"
              alt="Willovate One"
              className="navbar-logo-img"
            />
          </a>

          {/* Desktop Navigation */}
          <div className="navbar-menu desktop">
            <a href="#product" onClick={() => handleNavClick('product')}>Product</a>
            <a href="#solutions" onClick={() => handleNavClick('solutions')}>Solutions</a>
            <a
              href="#templates"
              onClick={(e) => {
                e.preventDefault()
                handleNavClick('templates')
              }}
            >
              Templates
            </a>
            <a href="#pricing" onClick={() => handleNavClick('pricing')}>Pricing</a>
          </div>

          {/* Right CTA */}
          <div className="navbar-right desktop">
            <a href="#login" className="nav-link">Log in</a>
            <button className="btn-start-free" type="button" onClick={onStartFree}>
              Start free
            </button>
          </div>

          {/* Mobile Hamburger Toggle */}
          <button
            className="mobile-menu-toggle"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            aria-label="Toggle mobile menu"
            type="button"
          >
            <span className={mobileMenuOpen ? 'open' : ''}></span>
            <span className={mobileMenuOpen ? 'open' : ''}></span>
            <span className={mobileMenuOpen ? 'open' : ''}></span>
          </button>

          {/* Mobile Slide-out Menu */}
          {mobileMenuOpen && (
            <div className="navbar-menu mobile">
              <a href="#product" onClick={() => handleNavClick('product')}>Product</a>
              <a href="#solutions" onClick={() => handleNavClick('solutions')}>Solutions</a>
              <a
                href="#templates"
                onClick={(e) => {
                  e.preventDefault()
                  handleNavClick('templates')
                }}
              >
                Templates
              </a>
              <a href="#pricing" onClick={() => handleNavClick('pricing')}>Pricing</a>
              <div className="mobile-actions">
                <a href="#login" className="nav-link">Log in</a>
                <button className="btn-start-free" type="button" onClick={onStartFree}>
                  Start free
                </button>
              </div>
            </div>
          )}
        </div>
      </nav>
    </header>
  )
}

